    commuters.append((t, s, e))

# Create adjacency list for stations
adj_list = [[] for _ in range(n)]
for i in range(n - 1):
    adj_list[i].append((i + 1, distances[i]))
    adj_list[i + 1].append((i, distances[i]))

# Dijkstra's algorithm to find shortest path with nitro
def dijkstra(start, end, nitro_units):
    pq = [(0, start, 0)]  # (time, station, nitro_used)
    dist = [[float('inf')] * (K + 1) for _ in range(n)]
    dist[start][0] = 0
    while pq:
        time, station, nitro_used = heapq.heappop(pq)
        if station == end:
            return time
        if time > dist[station][nitro_used]:
            continue
        for neighbor, edge_time in adj_list[station]:
            new_time = time + edge_time
            if new_time < dist[neighbor][nitro_used]:
                dist[neighbor][nitro_used] = new_time
                heapq.heappush(pq, (new_time, neighbor, nitro_used))
            if nitro_used < K:
                reduced_time = max(new_time - 1, 0)
                if reduced_time < dist[neighbor][nitro_used + 1]:
                    dist[neighbor][nitro_used + 1] = reduced_time
                    heapq.heappush(pq, (reduced_time, neighbor, nitro_used + 1))
    return float('inf')

# Calculate total travel time
total_time = 0
for t, s, e in commuters:
    travel_time = dijkstra(s - 1, e - 1, K)
    total_time += travel_time

